'use server'

import { refresh } from 'next/cache'
import { cookies } from 'next/headers'

const NOTIFICATIONS_COOKIE = 'notifications-enabled'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get(NOTIFICATIONS_COOKIE)?.value === 'true'

  cookieStore.set(NOTIFICATIONS_COOKIE, String(!enabled), {
    httpOnly: true,
    maxAge: 60 * 60 * 24 * 365,
    path: '/',
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
  })

  refresh()
}
import { cookies } from 'next/headers'
import { toggleNotifications } from './actions'

export default async function Home() {
  const enabled =
    (await cookies()).get('notifications-enabled')?.value === 'true'

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}
import type { ReactNode } from 'react'

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

